// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Breadcrumb } from "@/registry/erbium/ui/breadcrumb";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import {\n  BreadcrumbList,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbSeparator,\n  BreadcrumbPage,\n} from \"@/registry/erbium/ui/breadcrumb\";\nimport { Breadcrumb } from \"@/registry/erbium/ui/breadcrumb\";\n\nconst Example = (args: { separator: string; currentPage: string }) => (\n  <Breadcrumb>\n    <BreadcrumbList>\n      <BreadcrumbItem>\n        <BreadcrumbLink href=\"#\">Home</BreadcrumbLink>\n      </BreadcrumbItem>\n      <BreadcrumbSeparator>{args.separator}</BreadcrumbSeparator>\n      <BreadcrumbItem>\n        <BreadcrumbPage>{args.currentPage}</BreadcrumbPage>\n      </BreadcrumbItem>\n    </BreadcrumbList>\n  </Breadcrumb>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/breadcrumb-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import EllipsisExample from "./variants/ellipsis";

const EllipsisSource = "import { BreadcrumbEllipsisDemo } from \"../examples/breadcrumb-ellipsis\";\n\nconst Example = () => <BreadcrumbEllipsisDemo />;\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import { BreadcrumbBasic } from \"../examples/breadcrumb-basic\";\n\nconst Example = () => <BreadcrumbBasic />;\n\nexport default Example;\n";

import DropdownExample from "./variants/dropdown";

const DropdownSource = "import { BreadcrumbDropdown } from \"../examples/breadcrumb-dropdown\";\n\nconst Example = () => <BreadcrumbDropdown />;\n\nexport default Example;\n";

import CustomSeparatorExample from "./variants/custom-separator";

const CustomSeparatorSource = "import { BreadcrumbSeparatorDemo } from \"../examples/breadcrumb-separator\";\n\nconst Example = () => <BreadcrumbSeparatorDemo />;\n\nexport default Example;\n";

import LinkComponentExample from "./variants/link-component";

const LinkComponentSource = "import { BreadcrumbLinkDemo } from \"../examples/breadcrumb-link\";\n\nconst Example = () => <BreadcrumbLinkDemo />;\n\nexport default Example;\n";

const meta = {
  component: Breadcrumb,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nUse a hierarchy of links to show the path to the current resource.\n\n**Import:** `@/registry/erbium/ui/breadcrumb`\n\n## Usage\n\n```tsx\nimport {\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n} from \"@/registry/erbium/ui/breadcrumb\";\n```\n\n```tsx\n<Breadcrumb>\n  <BreadcrumbList>\n    <BreadcrumbItem>\n      <BreadcrumbLink render={<a href=\"/\" />}>Home</BreadcrumbLink>\n    </BreadcrumbItem>\n    <BreadcrumbSeparator />\n    <BreadcrumbItem>\n      <BreadcrumbLink render={<a href=\"/components\" />}>Components</BreadcrumbLink>\n    </BreadcrumbItem>\n    <BreadcrumbSeparator />\n    <BreadcrumbItem>\n      <BreadcrumbPage>Breadcrumb</BreadcrumbPage>\n    </BreadcrumbItem>\n  </BreadcrumbList>\n</Breadcrumb>\n```\n\n## Composition\n\nUse the following composition to build a `Breadcrumb`:\n\n```text\nBreadcrumb\n└── BreadcrumbList\n    ├── BreadcrumbItem\n    │   └── BreadcrumbLink\n    ├── BreadcrumbSeparator\n    ├── BreadcrumbItem\n    │   └── BreadcrumbLink\n    ├── BreadcrumbSeparator\n    └── BreadcrumbItem\n        └── BreadcrumbPage\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [mergeProps](https://base-ui.com/react/utils/merge-props)\n- [useRender](https://base-ui.com/react/utils/use-render)",
      },
    },
  },
} satisfies Meta<typeof Breadcrumb>;

export default { ...meta, title: "Components/Breadcrumb",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{ separator: string; currentPage: string }> = {
  args: { separator: "/", currentPage: "Current page" },
  argTypes: { separator: { control: "text" }, currentPage: { control: "text" } },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Ellipsis: Story = {
  name: "Collapsed",
  parameters: {
    docs: {
      description: { story: "We provide a `<BreadcrumbEllipsis />` component to show a collapsed state when the breadcrumb is too long." },
      source: { code: EllipsisSource },
    },
  },
  render: EllipsisExample,
};

export const Basic: Story = {
  parameters: {
    docs: {
      description: { story: "A basic breadcrumb with a home link and a components link." },
      source: { code: BasicSource },
    },
  },
  render: BasicExample,
};

export const Dropdown: Story = {
  parameters: {
    docs: {
      description: { story: "You can compose `<BreadcrumbItem />` with a `<DropdownMenu />` to create a dropdown in the breadcrumb." },
      source: { code: DropdownSource },
    },
  },
  render: DropdownExample,
};

export const CustomSeparator: Story = {
  parameters: {
    docs: {
      description: { story: "Use a custom component as `children` for `<BreadcrumbSeparator />` to create a custom separator." },
      source: { code: CustomSeparatorSource },
    },
  },
  render: CustomSeparatorExample,
};

export const LinkComponent: Story = {
  parameters: {
    docs: {
      description: { story: "To use a custom link component from your routing library, you can use the `render` prop on `<BreadcrumbLink />`." },
      source: { code: LinkComponentSource },
    },
  },
  render: LinkComponentExample,
};

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/registry/erbium/ui/breadcrumb";
export default function Demo() {
  return (
    <Breadcrumb>
      <BreadcrumbList>
        <BreadcrumbItem>
          <BreadcrumbLink href="/">Home</BreadcrumbLink>
        </BreadcrumbItem>
        <BreadcrumbSeparator />
        <BreadcrumbItem>
          <BreadcrumbPage>Components</BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </Breadcrumb>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import DotIcon from "@hugeicons/core-free-icons/DotIcon";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/registry/erbium/ui/breadcrumb";

export function BreadcrumbSeparatorDemo() {
  return (
    <Breadcrumb>
      <BreadcrumbList>
        <BreadcrumbItem>
          <BreadcrumbLink render={<a href="/" />}>Home</BreadcrumbLink>
        </BreadcrumbItem>
        <BreadcrumbSeparator>
          <HugeiconsIcon icon={DotIcon} />
        </BreadcrumbSeparator>
        <BreadcrumbItem>
          <BreadcrumbLink render={<a href="/docs/installation" />}>Installation</BreadcrumbLink>
        </BreadcrumbItem>
        <BreadcrumbSeparator>
          <HugeiconsIcon icon={DotIcon} />
        </BreadcrumbSeparator>
        <BreadcrumbItem>
          <BreadcrumbPage>Breadcrumb</BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </Breadcrumb>
  );
}

import { BreadcrumbBasic } from "../examples/breadcrumb-basic";

const Example = () => <BreadcrumbBasic />;

export default Example;

import { BreadcrumbSeparatorDemo } from "../examples/breadcrumb-separator";

const Example = () => <BreadcrumbSeparatorDemo />;

export default Example;

import { BreadcrumbDropdown } from "../examples/breadcrumb-dropdown";

const Example = () => <BreadcrumbDropdown />;

export default Example;

import { BreadcrumbEllipsisDemo } from "../examples/breadcrumb-ellipsis";

const Example = () => <BreadcrumbEllipsisDemo />;

export default Example;

import { BreadcrumbLinkDemo } from "../examples/breadcrumb-link";

const Example = () => <BreadcrumbLinkDemo />;

export default Example;

import Demo from "../examples/breadcrumb-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import {
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbSeparator,
  BreadcrumbPage,
} from "@/registry/erbium/ui/breadcrumb";
import { Breadcrumb } from "@/registry/erbium/ui/breadcrumb";

const Example = (args: { separator: string; currentPage: string }) => (
  <Breadcrumb>
    <BreadcrumbList>
      <BreadcrumbItem>
        <BreadcrumbLink href="#">Home</BreadcrumbLink>
      </BreadcrumbItem>
      <BreadcrumbSeparator>{args.separator}</BreadcrumbSeparator>
      <BreadcrumbItem>
        <BreadcrumbPage>{args.currentPage}</BreadcrumbPage>
      </BreadcrumbItem>
    </BreadcrumbList>
  </Breadcrumb>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}
